          else {
            const d = rest.filter(([l]) => declRe.test(l));
            if (d.length !== 1 || /^\s*public\b/.test(d[0][0])) continue;
            declIdx = d[0][1];
            const others = rest.filter(([, j]) => j !== declIdx);
            if (!others.every(([l]) => new RegExp(`\\b${name}\\s*\\.\\s*cancel\\s*\\(\\s*\\)|\\b${name}\\s*(==|!=)\\s*null|\\b${name}\\s*=\\s*null\\s*;`).test(l))) continue;
          }
