        const call = `NxPerf.timer("${key(name || methodAt(i))}", ${args[2]}, ${args[3]}, ${args[1]});`;
        const to = `${m[1]}${name ? `${m[2] ? "NxPerf.Timer " : ""}${m[3]} = ` : ""}${call}`;
        fixes.push({ file: f.rel, line: i + 1, kind: "perf-timer", from: lines[i].trim().slice(0, 160), to: to.trim().slice(0, 160) });
        lines[i] = to;
        if (declIdx >= 0) lines[declIdx] = lines[declIdx].replace(/\bBukkitTask\b/, "NxPerf.Timer");
        tfix = true;
      }
      changed = changed || tfix;
