    if (addNxPerfImport(lines, perfPkg)) fixes.push({ file: f.rel, line: 1, kind: "missing-import", from: "", to: `import ${perfPkg}.NxPerf;` });
    fs.writeFileSync(f.abs, lines.join("\n"));
  }
  return { fixes };
}
