import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/* eslint-disable @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any */
const AF = require("../services/modbuilder/autofix.js") as any;
const PERF = require("../services/modbuilder/perf.js") as any;

const PKG = "dev.nxeon.plugins.demo.nxperf";
function ws(files: Record<string, string>) {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), "mb-fp-"));
  for (const [rel, text] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); fs.writeFileSync(path.join(d, rel), text); }
  return d;
}
const rel = "src/main/java/dev/nxeon/plugins/demo/Give.java";
const run = (src: string) => { const d = ws({ [rel]: src }); const f = [{ rel, abs: path.join(d, rel) }]; const r = AF.fixPerf(f, PKG); return { r, out: fs.readFileSync(path.join(d, rel), "utf8"), hits: PERF.perfcheck(f) }; };

describe("perf guards without a model turn", () => {
  const HEAD = "package dev.nxeon.plugins.demo;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import java.util.*;
class Give {
";
  it("wraps the leftover-drop loop in NxPerf.spawnAllowed and the pre-check no longer fires (first1: 7 builds)", () => {
    const src = `${HEAD}  void give(Player target, ItemStack item) {
    Map<Integer, ItemStack> leftover = target.getInventory().addItem(item);
    for (ItemStack extra : leftover.values()) {
        target.getWorld().dropItemNaturally(target.getLocation(), extra);
    }
  }
}
`;
    const before = PERF.perfcheck([{ rel, abs: path.join(ws({ [rel]: src }), rel) }]);
    assert.deepEqual(before.map((h: any) => h.rule), ["perf-spawn-in-loop"]);
    const { r, out, hits } = run(src);
    assert.deepEqual(r.fixes.map((f: any) => f.kind), ["perf-spawn-guard", "missing-import"]);
    assert.match(out, /import dev\.nxeon\.plugins\.demo\.nxperf\.NxPerf;/);
    assert.match(out, /if \(NxPerf\.spawnAllowed\("give-give", target\.getLocation\(\)\.getChunk\(\)\)\) \{
\s+target\.getWorld\(\)\.dropItemNaturally\(target\.getLocation\(\), extra\);
\s+\}/);
    assert.equal(hits.length, 0);
  });
  it("leaves alone: results that are used, braceless bodies, lines with several statements, spawns outside a loop, files already bounded", () => {
    const cases = [
      `${HEAD}  void a(Player p, List<ItemStack> l) {
    for (ItemStack i : l) {
      Item it = p.getWorld().dropItemNaturally(p.getLocation(), i);
      it.setPickupDelay(0);
    }
  }
}
`,
      `${HEAD}  void a(Player p, List<ItemStack> l, boolean x) {
    for (ItemStack i : l) {
      if (x)
        p.getWorld().dropItemNaturally(p.getLocation(), i);
      else p.sendMessage("n");
    }
  }
}
`,
      `${HEAD}  void a(Player p, ItemStack i) {
    p.getWorld().dropItemNaturally(p.getLocation(), i);
  }
}
`,
      `${HEAD}  void a(Player p, List<ItemStack> l) {
    for (ItemStack i : l) {
      if (NxPerf.spawnAllowed("x", p.getLocation().getChunk())) p.getWorld().dropItemNaturally(p.getLocation(), i);
      p.getWorld().dropItem(p.getLocation(), i);
    }
  }
}
`,
      `${HEAD}  void a(Player p, List<ItemStack> l) {
    for (ItemStack i : l) { p.getWorld().dropItem(p.getLocation(), i); p.sendMessage("x"); }
  }
}
`,
    ];
    for (const src of cases) { const { r, out } = run(src); assert.equal(r.fixes.length, 0, src); assert.equal(out, src); }
  });
  it("turns a statement-form runTaskTimer and an assigned BukkitTask field into NxPerf.timer, never the async or unknown forms", () => {
    const base = "package dev.nxeon.plugins.demo;
import org.bukkit.Bukkit;
import org.bukkit.scheduler.BukkitTask;
class Give {
";
    const a = `${base}  private BukkitTask autosaveTask;
  void on() {
    autosaveTask = Bukkit.getScheduler().runTaskTimer(this, economy::save, 6000L, 6000L);
  }
  void off() {
    if (autosaveTask != null) autosaveTask.cancel();
  }
}
`;
    const ra = run(a);
    assert.match(ra.out, /private NxPerf\.Timer autosaveTask;/);
    assert.match(ra.out, /autosaveTask = NxPerf\.timer\("give-autosaveTask", 6000L, 6000L, economy::save\);/);
    assert.equal(ra.hits.length, 0);
    const b = `${base}  void on() {
    Bukkit.getScheduler().runTaskTimer(this, () -> tick(Bukkit.getOnlinePlayers()), 20L, 40L);
  }
}
`;
    assert.match(run(b).out, /NxPerf\.timer\("give-on", 20L, 40L, \(\) -> tick\(Bukkit\.getOnlinePlayers\(\)\)\);/);
    // the task object is used for something a Timer cannot do
    const c = `${base}  private BukkitTask t;
  void on() {
    t = Bukkit.getScheduler().runTaskTimer(this, () -> {}, 1L, 2L);
    int id = t.getTaskId();
  }
}
`;
    assert.equal(run(c).r.fixes.length, 0);
    // async work must not be moved to the main thread
    const d = `${base}  void on() {
    Bukkit.getScheduler().runTaskTimerAsynchronously(this, () -> {}, 1L, 2L);
  }
}
`;
    assert.equal(run(d).r.fixes.length, 0);
    // an anonymous BukkitRunnable is left to the model
    const e = `${base}  void on() {
    new BukkitRunnable() { public void run() {} }.runTaskTimer(this, 1L, 2L);
  }
}
`;
    assert.equal(run(e).r.fixes.length, 0);
  });
  it("never edits the watchdog files and refuses a bad package", () => {
    const d = ws({ "src/main/java/dev/nxeon/plugins/demo/nxperf/NxPerf.java": "class NxPerf { void f(java.util.List<Object> l){ for (Object o : l) { w.dropItem(loc, o); } } }" });
    const f = [{ rel: "src/main/java/dev/nxeon/plugins/demo/nxperf/NxPerf.java", abs: path.join(d, "src/main/java/dev/nxeon/plugins/demo/nxperf/NxPerf.java") }];
    assert.equal(AF.fixPerf(f, PKG).fixes.length, 0);
    assert.equal(AF.fixPerf(f, "Bad Pkg").fixes.length, 0);
  });
});
E
