// One asset round (only when textures or sounds are allowed): HARD problems go back to the model (bounded by
// MAX_ASSET_REPAIRS and the overall repair cap), soft ones once; when the repairs are used up, specs that still fail
// are DROPPED with a customer-visible reason (downgrade), never shipped. Returns a repair problem or null.
function pluginYmlText(ws) { try { return fs.readFileSync(path.join(ws, "src/main/resources/plugin.yml"), "utf8"); } catch { return ""; } }
function assetRound(ws, rec, st, repairs) {
  if (!texOn(rec) && !sndOn(rec) && !dpOn(rec) && !creOn(rec)) return null;
  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
  const t = texOn(rec) ? TX.checkWorkspaceTextures(ws, { namespace: rec.assets.namespace, javaFiles: java, legacy: legacyTex(rec) }) : { files: [], results: [], problems: [], soft: [] };
  const sd = sndOn(rec) ? SND.checkWorkspaceSounds(ws, { namespace: rec.assets.namespace, javaFiles: java, library: libOn(rec) }) : { files: [], results: [], problems: [], soft: [] };
  const dp = dpOn(rec) ? DPK.checkWorkspaceDatapacks(ws, { namespace: rec.assets.namespace, mcVersion: rec.mcVersion, javaFiles: java, worldgen: wgOn(rec) }) : { files: [], results: [], problems: [], soft: [] };
  const cr = creOn(rec) ? CR.checkWorkspaceCreatures(ws, { namespace: rec.assets.namespace, javaFiles: java, pluginYml: pluginYmlText(ws) }) : { files: [], results: [], problems: [], soft: [] };
  const okTextures = () => t.results.filter((r) => r.ok).map((r) => r.name);
  const im = imOn(rec) ? IMS.checkWorkspaceItemModels(ws, { mcVersion: rec.mcVersion, textures: okTextures() }) : { files: [], results: [], problems: [], soft: [] };
  if (!t.files.length && !sd.files.length && !dp.files.length && !cr.files.length && !im.files.length) return null;
  const canRepair = st.assetRepairs < MAX_ASSET_REPAIRS && repairs < MAX_REPAIRS;
  const soft = st.softAsked ? [] : [...t.soft, ...sd.soft, ...dp.soft, ...cr.soft, ...im.soft];
  const hard = [...t.problems, ...sd.problems, ...dp.problems, ...cr.problems, ...im.problems];
  const verdictsAll = (final) => { liveAssetVerdicts(rec, "texture", t.results, final); liveAssetVerdicts(rec, "sound", sd.results, final); liveAssetVerdicts(rec, "datapack", dp.results, final); liveAssetVerdicts(rec, "creature", cr.results, final); liveAssetVerdicts(rec, "itemmodel", im.results, final); };
  if (canRepair && (hard.length || soft.length)) {
    verdictsAll(false);
    if (soft.length) st.softAsked = true;
    const lines = [...hard, ...soft];
    const kinds = [t.files.length, sd.files.length, dp.files.length, cr.files.length, im.files.length].filter(Boolean).length;
    const what = kinds > 1 ? "Asset" : cr.files.length ? "Creature" : dp.files.length ? "Data pack" : sd.files.length ? "Sound" : "Texture";
    return { kind: "asset", count: lines.length, text: lines.map((p) => `- ${p}`).join("\n"), say: `${what} check found ${lines.length} problem${lines.length > 1 ? "s" : ""}` };
  }
  verdictsAll(true);

