export type SoundProcessing = { lowpass: number | null; highpass: number | null; reverb: number; echo: { delay: number; feedback: number; mix: number } | null };
export type SoundVariant = { weight: number; layers: SoundLayer[]; processing: SoundProcessing };
export type SoundEvent = { event: string; role: SoundRole; category: SoundCategory; subtitle: string; variants: SoundVariant[] };
export type SoundSpec = { version: 1; name: string; events: SoundEvent[] };

/** Validator context: the library catalog (id -> seconds) and whether customer builds may use it. */
export type SoundSpecContext = { catalog: Record<string, number> | null; library: boolean };

const num = (v: unknown, lo: number, hi: number): v is number => typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi;
const r4 = (v: number) => Math.round(v * 10000) / 10000;
const DEFAULT_CATEGORY: Record<SoundRole, SoundCategory> = { ambient: "hostile", hurt: "hostile", death: "hostile", attack: "hostile", step: "hostile", ability: "player", fire: "player", reload: "player", spawn: "hostile", ui: "master", other: "neutral" };

/** Estimated seconds of one variant (layers' extent after pitch + effect tails), from the catalog durations. */
export function estimateVariantSeconds(v: SoundVariant, catalog: Record<string, number> | null): number {
  let end = 0;
  for (const l of v.layers) {
