const SND = require("../services/modbuilder/sounds.js") as any;
const TXM = require("../services/modbuilder/textures.js") as any;
const SSMOD = require("../services/modbuilder/sound-spec.js") as any;

describe("sound lane: checker agrees with how the model writes keys, mechanical problems normalised", () => {
  const NS = "nx_42b6eb62";
  it("a key built from a literal prefix + suffix, or read from config.yml, is not 'never played'; a truly unused one still is", () => {
    const java = `class L { static final String P = "banshee."; void a(World w, Location l) { w.playSound(l, "${NS}:" + P + Kind.HURT.name().toLowerCase(), SoundCategory.HOSTILE, 1f, 1f); } enum Kind { HURT, DEATH } }`;
    assert.equal(SND.keyReachable("banshee.hurt", java, ""), true);
    assert.equal(SND.keyReachable("banshee.attack", java, ""), false);
    assert.equal(SND.keyReachable("handgun.fire", "class A { void f(){ p.playSound(l, cfg.getString(\"sounds.fire\"), c, 1f, 1f); } }", "sounds:\n  fire: nx_42b6eb62:handgun.fire\n"), true);
    assert.equal(SND.keyReachable("handgun.reload", "class A { }", "sounds:\n  fire: handgun.fire\n"), false);
    // a prefix literal alone (no suffix anywhere) proves nothing
    assert.equal(SND.keyReachable("door.open", `class A { String s = "door."; }`, ""), false);
  });
  it("texture names assembled at runtime count as referenced (shop_category_<id>)", () => {
    const j = `class S { NamespacedKey k(Category c) { return new NamespacedKey("${NS}", "shop_category_" + c.name().toLowerCase()); } enum Category { ARMOR, FOOD } }`;
    assert.equal(SND.keyReachable("shop_category_armor", j, ""), true);
    assert.equal(SND.keyReachable("shop_category_tools", j, ""), false);
    assert.equal(typeof TXM.checkWorkspaceTextures, "function");
  });
  it("normalises an over-long ambient variant, a stray field, an out-of-range number and a missing subtitle; never renames anything", () => {
    const spec = { version: 1, name: "cave_mine", note: "x", events: [{ event: "drone", role: "ambient", variants: [{ weight: 14, layers: [{ source: "synth:wail", length: 5.2, gain: 30, extra: 1 }] }] }] };
    const before = SSMOD.checkSoundSpec(spec, { catalog: null, library: false });
    assert.equal(before.ok, false);
    const { spec: n, notes } = SND.normaliseSoundSpec(spec, SSMOD);
    const after = SSMOD.checkSoundSpec(n, { catalog: null, library: false });
    assert.equal(after.ok, true, JSON.stringify(after) + notes.join("|"));
    assert.equal(n.name, "cave_mine"); assert.equal(n.events[0].event, "drone"); assert.equal(n.events[0].role, "ambient");
    assert.equal(n.events[0].variants[0].layers[0].source, "synth:wail");
    assert.equal(n.events[0].variants[0].weight, 10); assert.equal(n.events[0].variants[0].layers[0].gain, 12);
    assert.match(n.events[0].subtitle, /Cave mine drone/);
    assert.ok(notes.some((x: string) => /trimmed/.test(x)));
    assert.equal((spec.events[0] as any).subtitle, undefined, "the input is not modified");
  });
  it("leaves a good spec byte-identical and does not merge or drop different events", () => {
    const ex = JSON.parse(fs.readFileSync(path.join(__dirname, "../services/modbuilder/sound-example.json"), "utf8"));
    const r = SND.normaliseSoundSpec(ex, SSMOD);
    assert.deepEqual(r.spec, ex);
    assert.deepEqual(r.notes, []);
  });
});
