const { repairTriggers, journalStats } = require("../lib/cyrus/eval/stats.ts") as any;
describe("eval journal statistics", () => {
  it("names the repair triggers from a service record (events + precheck rules)", () => {
    const rec = {
      events: [
        { message: "Pre-check found 1 known API mistake. Fixing it automatically (fix 1 of 5)" },
        { message: "No design found. Fixing it automatically (fix 2 of 5)" },
        { message: "Sound check found 5 problems. Fixing it automatically (fix 3 of 5)" },
        { message: "Compiler found 2 errors. Fixing it automatically (fix 4 of 5)" },
        { message: "Compiled successfully" },
      ],
      precheck: [{ rule: "perf-spawn-in-loop", attempt: 1 }],
    };
    assert.deepEqual(repairTriggers(rec), ["perf-spawn-in-loop", "No design found", "Sound problems", "compile errors"].map((x) => (x === "Sound problems" ? "Sound check problems" : x)));
    assert.deepEqual(repairTriggers(null), []);
  });
  it("computes pass@1, repair share of spend and the top triggers", () => {
    const rows = [
      { job: "a", lane: "plain", pass: true, firstAttempt: true, repairs: 0, costUsd: 0.1 },
      { job: "b", lane: "plain", pass: true, firstAttempt: false, repairs: 1, costUsd: 0.3, triggers: ["perf-spawn-in-loop"] },
      { job: "c", lane: "sound", pass: true, firstAttempt: false, repairs: 2, costUsd: 0.6, triggers: ["Sound check problems", "perf-spawn-in-loop"] },
      { job: "d", lane: "sound", pass: false, firstAttempt: false, repairs: 0, costUsd: 0.0 },
    ];
    const s = journalStats(rows);
    assert.equal(s.n, 4);
    assert.equal(s.passAt1Pct, 25);
    assert.equal(s.finalPassPct, 75);
    assert.equal(s.repairedBuilds, 2);
    assert.equal(s.repairSharePct, 90);
    assert.deepEqual(s.triggers[0], { trigger: "perf-spawn-in-loop", repairs: 2, builds: 2 });
    assert.equal(s.lanes.find((l: any) => l.lane === "sound").n, 2);
  });
});
