const { planEstimate, MEASURED_SAKA } = require("../lib/cyrus/planner/estimate.ts") as any;
describe("plan estimate calibration (eval first1, Saka, retries included)", () => {
  const T = "A ruby sword with a custom texture and a /ruby command that gives it.";
  it("covers the measured p80 of each lane group and states an up-to figure above the range", () => {
    for (const [lane, g] of [["texture", "texture"], ["sound", "sound"], ["designItem", "designer"], ["designMenu", "designer"]] as const) {
      const e = planEstimate(T, "saka", [lane]);
      assert.ok(e.usd[1] >= MEASURED_SAKA[g].p80, `${lane}: high ${e.usd[1]} >= p80 ${MEASURED_SAKA[g].p80}`);
      assert.ok(e.usd[0] >= Math.round(0.7 * MEASURED_SAKA[g].p50 * 100) / 100 - 0.01, `${lane}: low`);
      assert.ok(e.upTo > e.usd[1] && e.upTo >= MEASURED_SAKA[g].p90, `${lane}: up to ${e.upTo}`);
    }
  });
  it("a plain build keeps its measured range (3 of 20 exceeded the high end) and gets an up-to figure; other models scale", () => {
    const p = planEstimate("A /heal command that heals the player.", "saka", []);
    assert.deepEqual(p.usd, [0.08, 0.18]);
    assert.ok(p.upTo >= 0.22 && p.upTo <= 0.3, String(p.upTo));
    const k = planEstimate(T, "katara", ["texture"]), y = planEstimate(T, "yakko", ["texture"]);
    assert.ok(k.usd[1] < planEstimate(T, "saka", ["texture"]).usd[1] && planEstimate(T, "saka", ["texture"]).usd[1] < y.usd[1]);
  });
});
